  'asgn.paste.hint': { es: 'Copia de tu Excel las columnas de conductor y matrícula y pégalas: cada uno solo podrá revisar su vehículo.', en: 'Copy the driver and plate columns from your spreadsheet and paste them: each driver can only inspect their own vehicle.', fr: 'Copiez depuis votre tableur les colonnes chauffeur et immatriculation et collez-les : chacun ne pourra contrôler que son véhicule.', de: 'Kopiere aus deiner Tabelle die Spalten Fahrer und Kennzeichen und füge sie ein: Jeder kann nur sein Fahrzeug prüfen.', it: 'Copia dal tuo foglio le colonne autista e targa e incollale: ognuno potrà controllare solo il suo veicolo.', pt: 'Copia da tua folha as colunas motorista e matrícula e cola-as: cada um só poderá inspecionar o seu veículo.' },
  'asgn.empty.hint': { es: 'Copia de tu Excel las columnas de conductor y matrícula y pégalas: cada uno solo podrá revisar su vehículo. O empieza con el de ayer.', en: 'Copy the driver and plate columns from your spreadsheet and paste them: each driver can only inspect their own vehicle. Or start from yesterday’s.', fr: 'Copiez depuis votre tableur les colonnes chauffeur et immatriculation et collez-les : chacun ne pourra contrôler que son véhicule. Ou partez de celui d’hier.', de: 'Kopiere aus deiner Tabelle die Spalten Fahrer und Kennzeichen und füge sie ein: Jeder kann nur sein Fahrzeug prüfen. Oder starte mit dem von gestern.', it: 'Copia dal tuo foglio le colonne autista e targa e incollale: ognuno potrà controllare solo il suo veicolo. Oppure parti da quello di ieri.', pt: 'Copia da tua folha as colunas motorista e matrícula e cola-as: cada um só poderá inspecionar o seu veículo. Ou começa pelo de ontem.' },
