  'lib.cargando': { es: 'Buscando portales que repiten…', en: 'Looking for repeat addresses…', fr: 'Recherche des adresses récurrentes…', de: 'Suche nach wiederkehrenden Adressen…', it: 'Ricerca di indirizzi ricorrenti…', pt: 'A procurar moradas repetidas…' },
