  'pk.bannerEdit':       { es: "Arrastra cada plaza sobre su marca en la foto. Pulsa una para girarla o cambiar su tamaño. Se guarda al pulsar «Guardar cambios».", en: "Drag each spot onto its mark in the photo. Tap one to rotate or resize it. Saved when you press “Save changes”.", fr: "Glissez chaque place sur sa marque dans la photo. Touchez-en une pour la pivoter ou la redimensionner. Enregistré avec « Enregistrer ».", de: "Ziehe jeden Platz auf seine Markierung im Foto. Tippe einen an, um ihn zu drehen oder zu skalieren. Gespeichert mit „Speichern“.", it: "Trascina ogni posto sul suo segno nella foto. Toccane uno per ruotarlo o ridimensionarlo. Si salva con “Salva modifiche”.", pt: "Arrasta cada lugar para a sua marca na foto. Toca num para rodar ou redimensionar. Guarda-se com “Guardar alterações”." },
  'pk.sinPlazas':        { es: "Sin plazas configuradas. Entra en «Editar plano» para añadirlas.", en: "No spots configured. Open “Edit map” to add them.", fr: "Aucune place configurée. Ouvrez « Modifier le plan » pour en ajouter.", de: "Keine Plätze konfiguriert. Öffne „Plan bearbeiten“, um welche anzulegen.", it: "Nessun posto configurato. Apri “Modifica mappa” per aggiungerli.", pt: "Sem lugares configurados. Abre “Editar mapa” para os adicionar." },
