  'pk.eAncho':           { es: "Ancho", en: "Width", fr: "Largeur", de: "Breite", it: "Larghezza", pt: "Largura" },
  'pk.eDuplicar':        { es: "Duplicar", en: "Duplicate", fr: "Dupliquer", de: "Duplizieren", it: "Duplica", pt: "Duplicar" },
  'pk.eEliminar':        { es: "Eliminar", en: "Delete", fr: "Supprimer", de: "Löschen", it: "Elimina", pt: "Eliminar" },
  'pk.vacioDia':         { es: "Aún no hay ninguna furgoneta colocada este día: ponlas en su plaza o pulsa «Como ayer» para repetir la última.", en: "No van has been placed on this day yet: put them in their spots or press “Like yesterday” to repeat the last one.", fr: "Aucun véhicule n'est encore placé ce jour-là : mettez-les à leur place ou appuyez sur « Comme hier » pour répéter la dernière.", de: "An diesem Tag ist noch kein Fahrzeug geparkt: stelle sie auf ihren Platz oder tippe auf „Wie gestern“, um den letzten zu übernehmen.", it: "Nessun furgone è ancora stato collocato in questo giorno: mettili al loro posto o premi «Come ieri» per ripetere l'ultimo.", pt: "Ainda não há nenhuma carrinha colocada neste dia: põe-nas no seu lugar ou carrega em «Como ontem» para repetir o último." },
  'pk.comoAyer':         { es: "Como ayer", en: "Like yesterday", fr: "Comme hier", de: "Wie gestern", it: "Come ieri", pt: "Como ontem" },
  'pk.comoAyerTip':      { es: "Pone cada furgoneta sin plaza en la última en que estuvo, sin mover las ya colocadas", en: "Puts each van without a spot in the last one it used, without moving those already placed", fr: "Met chaque véhicule sans place à la dernière qu'il a occupée, sans déplacer ceux déjà placés", de: "Stellt jedes Fahrzeug ohne Platz auf seinen letzten Platz, ohne die bereits geparkten zu verschieben", it: "Mette ogni furgone senza posto nell'ultimo che ha occupato, senza spostare quelli già collocati", pt: "Põe cada carrinha sem lugar no último em que esteve, sem mexer nas que já estão colocadas" },
  'pk.comoAyerOk.one':   { es: "{n} furgoneta colocada en su última plaza", en: "{n} van placed in its last spot", fr: "{n} véhicule placé à sa dernière place", de: "{n} Fahrzeug auf seinen letzten Platz gestellt", it: "{n} furgone collocato nel suo ultimo posto", pt: "{n} carrinha colocada no seu último lugar" },
  'pk.comoAyerOk.many':  { es: "{n} furgonetas colocadas en su última plaza", en: "{n} vans placed in their last spot", fr: "{n} véhicules placés à leur dernière place", de: "{n} Fahrzeuge auf ihren letzten Platz gestellt", it: "{n} furgoni collocati nel loro ultimo posto", pt: "{n} carrinhas colocadas no seu último lugar" },
  'pk.comoAyerParte':    { es: "Colocadas {n} de {t}: el resto, a mano", en: "{n} of {t} placed: place the rest by hand", fr: "{n} sur {t} placés : le reste à la main", de: "{n} von {t} geparkt: den Rest von Hand", it: "Collocati {n} su {t}: il resto a mano", pt: "Colocadas {n} de {t}: o resto, à mão" },
