  'dr.recoveryHint':  { es: "Usa tu correo de empresa y la contraseña que te dio la oficina. Si aún no tienes una, pide una clave temporal. Después podrás crear la tuya y añadir un correo personal.", en: "Use your work email and the temporary password from your office. After signing in, set your own password and add a personal recovery email.", fr: "Utilisez votre e-mail professionnel et le mot de passe temporaire fourni par votre bureau. Après connexion, définissez votre mot de passe et ajoutez une adresse personnelle de récupération.", de: "Nutze deine Firmen-E-Mail und das vorläufige Passwort vom Büro. Danach kannst du dein eigenes Passwort und eine private Wiederherstellungsadresse einrichten.", it: "Usa l’email aziendale e la password temporanea fornita dall’ufficio. Dopo l’accesso potrai impostare la tua password e un’email personale di recupero.", pt: "Usa o email de trabalho e a palavra-passe temporária fornecida pelo escritório. Depois de entrar, define a tua palavra-passe e adiciona um email pessoal de recuperação." },
  'dr.getEmailCode': { es: "Prefiero recibir un código por correo", en: "Use an email code instead", fr: "Recevoir plutôt un code par e-mail", de: "Stattdessen einen E-Mail-Code erhalten", it: "Preferisco ricevere un codice via email", pt: "Prefiro receber um código por email" },
