  'pg.ff.ponerTip': { es: "Rellena las vacías con la furgoneta principal o secundaria de cada conductor. Lo que ya está puesto no se toca.", en: "Fills empty cells with each driver's main or second van. What is already there is left alone.", fr: "Remplit les cases vides avec le fourgon principal ou secondaire de chaque chauffeur. Ce qui est déjà saisi reste.", de: "Füllt leere Felder mit dem Haupt- oder Zweitfahrzeug jedes Fahrers. Bereits Eingetragenes bleibt.", it: "Riempie le celle vuote con il furgone principale o secondario di ogni autista. Ciò che c'è già resta.", pt: "Preenche as vazias com a carrinha principal ou secundária de cada motorista. O que já está não se mexe." },
  'pg.ff.completar': { es: "Completar las que faltan", en: "Fill the rest", fr: "Compléter le reste", de: "Rest auffüllen", it: "Completa le altre", pt: "Completar as que faltam" },
  'pg.ff.completarTip': { es: "Pone también las libres a quien no tiene fija (nunca a los marcados «sin furgoneta fija»).", en: "Also gives free vans to drivers without an assigned one (never to those marked «no fixed van»).", fr: "Donne aussi les fourgons libres à qui n'en a pas d'attitré (jamais aux «sans fourgon attitré»).", de: "Gibt auch freie Fahrzeuge an Fahrer ohne festes (nie an «ohne festes Fahrzeug»).", it: "Assegna anche i liberi a chi non ha un furgone fisso (mai a chi è «senza furgone fisso»).", pt: "Dá também as livres a quem não tem fixa (nunca aos marcados «sem carrinha fixa»)." },
  'pg.ff.puestas': { es: "furgonetas puestas", en: "vans filled in", fr: "fourgons placés", de: "Fahrzeuge eingetragen", it: "furgoni assegnati", pt: "carrinhas postas" },
  'pg.ff.sinFijas': { es: "Nadie de esta hoja tiene todavía furgoneta fija. Entra en «Furgonetas fijas» y pulsa «Proponer reparto automático»: a partir de ahí se pondrán solas.", en: "Nobody on this sheet has an assigned van yet. Open «Assigned vans» and press «Suggest automatically»: from then on they are filled in automatically.", fr: "Personne sur cette feuille n'a encore de fourgon attitré. Ouvrez «Fourgons attitrés» et cliquez sur «Proposer automatiquement» : ensuite ils se placeront seuls.", de: "Noch niemand auf diesem Plan hat ein festes Fahrzeug. Öffne «Feste Fahrzeuge» und klicke «Automatisch vorschlagen»: danach werden sie automatisch eingetragen.", it: "Nessuno in questo piano ha ancora un furgone fisso. Apri «Furgoni assegnati» e premi «Proponi in automatico»: da lì in poi si assegneranno da soli.", pt: "Ninguém desta folha tem ainda carrinha fixa. Entra em «Carrinhas fixas» e carrega em «Propor automaticamente»: a partir daí põem-se sozinhas." },
  'pg.ff.ningunaNueva': { es: "No había ninguna que poner: las vacías son de conductores sin furgoneta fija.", en: "Nothing to fill: the empty rows belong to drivers without an assigned van.", fr: "Rien à placer : les lignes vides sont des chauffeurs sans fourgon attitré.", de: "Nichts einzutragen: die leeren Zeilen sind Fahrer ohne festes Fahrzeug.", it: "Niente da assegnare: le righe vuote sono di autisti senza furgone fisso.", pt: "Nada a pôr: as vazias são de motoristas sem carrinha fixa." },
  'pg.ff.sinNombre': { es: "No reconozco estos nombres (elige la furgoneta a mano o corrige el nombre):", en: "I don't recognise these names (pick the van by hand or fix the name):", fr: "Je ne reconnais pas ces noms (choisissez le fourgon à la main ou corrigez le nom) :", de: "Diese Namen erkenne ich nicht (Fahrzeug von Hand wählen oder Namen korrigieren):", it: "Non riconosco questi nomi (scegli il furgone a mano o correggi il nome):", pt: "Não reconheço estes nomes (escolhe a carrinha à mão ou corrige o nome):" },
