  'pg.ff.itvNoPuesta': { es: "No se ha puesto la {furgo} a {conductor}: ITV caducada desde el {fecha}. Si ya la pasó, cambia la fecha en su ficha.", en: "{furgo} was not given to {conductor}: MOT expired on {fecha}. If it has passed, change the date on its record.", fr: "Le {furgo} n'a pas été attribué à {conductor} : contrôle technique expiré depuis le {fecha}. S'il est passé, changez la date dans sa fiche.", de: "{furgo} wurde {conductor} nicht zugeteilt: TÜV abgelaufen seit {fecha}. Wenn er gemacht ist, ändere das Datum im Fahrzeugblatt.", it: "Il {furgo} non è stato assegnato a {conductor}: revisione scaduta dal {fecha}. Se l'ha già fatta, cambia la data nella sua scheda.", pt: "Não se pôs a {furgo} a {conductor}: IPO caducada desde {fecha}. Se já a fez, muda a data na sua ficha." },
  'ff.elegirCentro': { es: "Las furgonetas fijas van por centro: elige uno.", en: "Assigned vans are per site: choose one.", fr: "Les fourgons attitrés sont par site : choisissez-en un.", de: "Feste Fahrzeuge gelten pro Standort: wähle einen.", it: "I furgoni assegnati sono per sede: scegline una.", pt: "As carrinhas fixas são por centro: escolhe um." },
  'ff.tab.conductores': { es: "Conductores", en: "Drivers", fr: "Chauffeurs", de: "Fahrer", it: "Autisti", pt: "Motoristas" },
  'ff.tab.furgos': { es: "Furgonetas", en: "Vans", fr: "Fourgons", de: "Fahrzeuge", it: "Furgoni", pt: "Carrinhas" },
  'ff.tab.fila': { es: "Fila de aparcamiento", en: "Parking row", fr: "File de stationnement", de: "Parkreihe", it: "Fila di parcheggio", pt: "Fila de estacionamento" },
  'ff.col.titular': { es: "Titular", en: "Holder", fr: "Titulaire", de: "Vorrang", it: "Titolare", pt: "Titular" },
  'ff.col.ultima': { es: "Última", en: "Last", fr: "Dernier", de: "Zuletzt", it: "Ultimo", pt: "Última" },
  'ff.ninguna': { es: "— ninguna —", en: "— none —", fr: "— aucun —", de: "— keins —", it: "— nessuno —", pt: "— nenhuma —" },
  'ff.golpesTip': { es: "Últimos 180 días. Con una sola persona al volante: solo la llevaba esta persona, en un día, con las dos fotos. Posibles: estaba entre quienes la llevaron. Ninguno dice quién dio el golpe.", en: "Last 180 days. With only one driver: only this person had it, within a day, with both photos. Possible: was among those who had it. Neither says who caused the damage.", fr: "180 derniers jours. Avec un seul conducteur : seule cette personne l'avait, en un jour, avec les deux photos. Possibles : faisait partie de ceux qui l'avaient. Aucun ne dit qui a fait le choc.", de: "Letzte 180 Tage. Mit nur einem Fahrer: nur diese Person hatte es, innerhalb eines Tages, mit beiden Fotos. Möglich: war unter denen, die es fuhren. Keins davon sagt, wer den Schaden verursacht hat.", it: "Ultimi 180 giorni. Con un solo autista: lo aveva solo questa persona, in un giorno, con le due foto. Possibili: era tra chi lo guidava. Nessuno dei due dice chi ha fatto il danno.", pt: "Últimos 180 dias. Com uma só pessoa ao volante: só esta pessoa a levava, num dia, com as duas fotos. Possíveis: estava entre quem a levou. Nenhum diz quem deu o toque." },
  'ff.dias.one': { es: "{n} día", en: "{n} day", fr: "{n} jour", de: "{n} Tag", it: "{n} giorno", pt: "{n} dia" },
