  'ff.reserva': { es: "De reserva", en: "Spare", fr: "De réserve", de: "Ersatz", it: "Di riserva", pt: "De reserva" },
  'ff.vetadas': { es: "Furgonetas que no debe llevar", en: "Vans they must not drive", fr: "Fourgons qu'il ne doit pas conduire", de: "Fahrzeuge, die er nicht fahren soll", it: "Furgoni che non deve guidare", pt: "Carrinhas que não deve levar" },
  'ff.vetadasAnadir': { es: "Elige una para apartarla…", en: "Choose one to keep away…", fr: "Choisissez-en un à écarter…", de: "Eins zum Ausschließen wählen…", it: "Scegline uno da escludere…", pt: "Escolhe uma para afastar…" },
  'ff.vetadasOtra': { es: "Añadir otra…", en: "Add another…", fr: "En ajouter un autre…", de: "Weiteres hinzufügen…", it: "Aggiungine un altro…", pt: "Adicionar outra…" },
  'ff.vetadasQuitar': { es: "Quitar {p} de las que no debe llevar", en: "Remove {p} from the vans they must not drive", fr: "Retirer {p} des fourgons à éviter", de: "{p} aus den ausgeschlossenen Fahrzeugen entfernen", it: "Togli {p} dai furgoni da evitare", pt: "Tirar {p} das que não deve levar" },
  'ff.vetadasAyuda': { es: "«Poner furgonetas» y las sugerencias nunca se las darán. A mano, en la plantilla o en la asignación, se le pueden seguir poniendo.", en: "“Fill in vans” and the suggestions will never give them to this driver. By hand, in the sheet or the assignment, they can still be set.", fr: "« Placer les fourgons » et les suggestions ne les lui donneront jamais. À la main, dans la feuille ou l'affectation, on peut encore les lui mettre.", de: "„Fahrzeuge eintragen“ und die Vorschläge geben sie ihm nie. Von Hand, im Tagesplan oder in der Zuweisung, geht es weiterhin.", it: "«Assegna furgoni» e i suggerimenti non glieli daranno mai. A mano, nel foglio o nell'assegnazione, si possono ancora mettere.", pt: "«Pôr carrinhas» e as sugestões nunca lhas darão. À mão, na folha ou na atribuição, ainda se podem pôr." },
  'ff.noLleva': { es: "No debe llevar", en: "Must not drive", fr: "Ne doit pas conduire", de: "Nicht fahren", it: "Non deve guidare", pt: "Não deve levar" },
  'ff.vetadaFuera': { es: "De baja o de otro centro", en: "Retired or at another site", fr: "Retiré ou d'un autre centre", de: "Abgemeldet oder anderer Standort", it: "Dismesso o di un'altra sede", pt: "De baixa ou de outro centro" },
  'ff.aManoChip': { es: "Se elige cada día a mano", en: "Chosen by hand each day", fr: "Choisi à la main chaque jour", de: "Wird täglich von Hand gewählt", it: "Si sceglie a mano ogni giorno", pt: "Escolhe-se à mão cada dia" },
