  'ff.golpesSeg.one': { es: "{n} golpe con una sola persona al volante", en: "{n} damage with only one driver", fr: "{n} choc avec un seul conducteur", de: "{n} Schaden mit nur einem Fahrer", it: "{n} danno con un solo autista", pt: "{n} toque com uma só pessoa ao volante" },
