  'ff.f.nadie': { es: "Nadie la tiene todavía", en: "Nobody has it yet", fr: "Personne ne l'a encore", de: "Noch niemandem zugeteilt", it: "Nessuno ce l'ha ancora", pt: "Ninguém a tem ainda" },
  'ff.f.aQuien': { es: "¿A quién se la doy?", en: "Who should get it?", fr: "À qui le donner ?", de: "Wem geben?", it: "A chi lo do?", pt: "A quem a dou?" },
  'ff.dlg.aQuienT': { es: "¿A quién le doy la {p}?", en: "Who should get {p}?", fr: "À qui donner le {p} ?", de: "Wer bekommt {p}?", it: "A chi do il {p}?", pt: "A quem dou a {p}?" },
