  'pg.pegaTexto': { es: "…o pega el texto (si no cabe en una captura)", en: "…or paste the text (if it doesn't fit in one screenshot)", fr: "…ou collez le texte (si ça ne tient pas dans une capture)", de: "…oder füge den Text ein (wenn ein Screenshot nicht reicht)", it: "…o incolla il testo (se non entra in uno screenshot)", pt: "…ou cola o texto (se não couber numa captura)" },
  'pg.pegaHint': { es: "Pega tal cual (columnas separadas por tabs o espacios). La IA lo entiende.", en: "Paste as-is (columns separated by tabs or spaces). The AI understands it.", fr: "Collez tel quel (colonnes séparées par tabulations ou espaces). L'IA comprend.", de: "Einfach einfügen (Spalten mit Tabs oder Leerzeichen). Die KI versteht es.", it: "Incolla così com'è (colonne con tab o spazi). L'IA lo capisce.", pt: "Cola tal e qual (colunas separadas por tabs ou espaços). A IA entende." },
  'pg.borrar': { es: "Borrar", en: "Clear", fr: "Effacer", de: "Löschen", it: "Cancella", pt: "Apagar" },
