  'pg.volverHoja': { es: "Volver a la hoja", en: "Back to the roster", fr: "Retour à la feuille", de: "Zurück zum Plan", it: "Torna al piano", pt: "Voltar à escala" },
  'pg.desdeAsig': { es: "¿Ya está hecha la Asignación de hoy?", en: "Is today’s dispatch already done?", fr: "L’affectation du jour est déjà faite ?", de: "Ist die heutige Tagesplanung schon fertig?", it: "L’assegnazione di oggi è già fatta?", pt: "A atribuição de hoje já está feita?" },
  'pg.desdeAsigDesc': { es: "Monta la hoja con quién lleva qué vehículo y en qué ruta, sin pegar nada.", en: "Builds the roster from who drives which vehicle and route, no pasting needed.", fr: "Crée la feuille avec qui conduit quel véhicule et quelle tournée, sans rien coller.", de: "Erstellt den Plan aus Fahrer, Fahrzeug und Route, ohne Einfügen.", it: "Crea il piano con chi guida quale veicolo e percorso, senza incollare nulla.", pt: "Monta a escala com quem leva cada veículo e rota, sem colar nada." },
  'pg.usarAsig': { es: "Usar la asignación", en: "Use the dispatch", fr: "Utiliser l’affectation", de: "Tagesplanung verwenden", it: "Usa l’assegnazione", pt: "Usar a atribuição" },
  'pg.enBlanco': { es: "Empezar en blanco", en: "Start blank", fr: "Commencer vide", de: "Leer beginnen", it: "Inizia vuoto", pt: "Começar em branco" },
  'pg.sinAsig': { es: "La Asignación de hoy está vacía en este centro. Hazla primero o pega la lista abajo.", en: "Today’s dispatch is empty for this site. Do it first or paste the list below.", fr: "L’affectation du jour est vide pour ce centre. Faites-la d’abord ou collez la liste ci-dessous.", de: "Die heutige Tagesplanung ist für diesen Standort leer. Erst erstellen oder unten die Liste einfügen.", it: "L’assegnazione di oggi è vuota per questa sede. Falla prima o incolla la lista qui sotto.", pt: "A atribuição de hoje está vazia neste centro. Faz primeiro ou cola a lista abaixo." },
  'pg.redondeo': { es: "Hora de salida:", en: "Departure time:", fr: "Heure de départ :", de: "Abfahrtszeit:", it: "Ora di partenza:", pt: "Hora de saída:" },
  'pg.redondeoNo': { es: "tal cual", en: "as it is", fr: "telle quelle", de: "wie angegeben", it: "così com’è", pt: "tal como está" },
  'pg.tramosDe': { es: "bajar a tramos de", en: "round down to", fr: "arrondir par tranches de", de: "abrunden auf", it: "arrotonda a blocchi di", pt: "arredondar a blocos de" },
  'pg.sinIA': { es: "La IA no respondió: el texto se ha leído por columnas. Revisa las filas antes de descargar.", en: "The AI did not respond: the text was read by columns. Check the rows before downloading.", fr: "L’IA n’a pas répondu : le texte a été lu par colonnes. Vérifiez les lignes avant de télécharger.", de: "Die KI hat nicht geantwortet: Der Text wurde spaltenweise gelesen. Zeilen vor dem Download prüfen.", it: "L’IA non ha risposto: il testo è stato letto per colonne. Controlla le righe prima di scaricare.", pt: "A IA não respondeu: o texto foi lido por colunas. Revê as linhas antes de descarregar." },
  'pg.nadaLeido': { es: "No se ha encontrado ningún conductor en lo que has pegado. Comprueba que cada línea tenga un nombre.", en: "No driver was found in what you pasted. Check that each line has a name.", fr: "Aucun chauffeur trouvé dans le texte collé. Vérifiez que chaque ligne a un nom.", de: "Im eingefügten Text wurde kein Fahrer gefunden. Prüfe, ob jede Zeile einen Namen hat.", it: "Nessun autista trovato nel testo incollato. Controlla che ogni riga abbia un nome.", pt: "Não se encontrou nenhum motorista no que colaste. Confirma que cada linha tem um nome." },

