  'alta.pasos': { es: "Los pasos del arranque", en: "Setup steps", fr: "Les étapes du démarrage", de: "Die Schritte zum Start", it: "I passi per partire", pt: "Os passos do arranque" },
  'alta.hecho': { es: "Hecho", en: "Done", fr: "Fait", de: "Erledigt", it: "Fatto", pt: "Feito" },
