  'alta.cambiarLista': { es: "Cambiar la lista", en: "Edit the list", fr: "Modifier la liste", de: "Liste ändern", it: "Modifica l’elenco", pt: "Mudar a lista" },
  'alta.excel': { es: "Subir un Excel", en: "Upload a spreadsheet", fr: "Importer un fichier Excel", de: "Excel-Datei hochladen", it: "Carica un Excel", pt: "Carregar um Excel" },
  'alta.cancelar': { es: "Cancelar", en: "Cancel", fr: "Annuler", de: "Abbrechen", it: "Annulla", pt: "Cancelar" },
