  'alta.imp.f.arrastra': { es: "Arrastra el Excel de tus furgonetas", en: "Drop the spreadsheet with your vans", fr: "Dépose le fichier Excel de tes camionnettes", de: "Zieh die Excel-Datei deiner Fahrzeuge hierher", it: "Trascina l’Excel dei tuoi furgoni", pt: "Arrasta o Excel das tuas carrinhas" },
  'alta.imp.f.pie': { es: "el tuyo, el de la gestoría o el del renting", en: "yours, your accountant’s or your leasing company’s", fr: "le tien, celui du comptable ou celui du loueur", de: "deine eigene, die vom Steuerbüro oder vom Leasinggeber", it: "il tuo, quello del commercialista o quello del noleggio", pt: "o teu, o da contabilidade ou o do renting" },
