  'alta.imp.pegarAyuda': { es: "Copia las filas en Excel (con la cabecera) y pégalas aquí.", en: "Copy the rows in your spreadsheet (with the header) and paste them here.", fr: "Copie les lignes dans Excel (avec l’en-tête) et colle-les ici.", de: "Kopiere die Zeilen in Excel (mit Kopfzeile) und füge sie hier ein.", it: "Copia le righe in Excel (con l’intestazione) e incollale qui.", pt: "Copia as linhas no Excel (com o cabeçalho) e cola-as aqui." },
  'alta.imp.plantilla': { es: "Descargar plantilla", en: "Download template", fr: "Télécharger le modèle", de: "Vorlage herunterladen", it: "Scarica il modello", pt: "Descarregar modelo" },
