  'alta.imp.queColumna': { es: "¿Qué columna es la matrícula?", en: "Which column is the number plate?", fr: "Quelle colonne contient l’immatriculation ?", de: "Welche Spalte ist das Kennzeichen?", it: "Quale colonna è la targa?", pt: "Que coluna é a matrícula?" },
